#pragma once
// Build-provenance mark. A signed, whitened record (src/core/prov_data.h, generated by
// tools/sign/make_record.py) is compiled into the firmware so that an image built from this
// source - even with a replaced UI - can be proven to descend from the REDLINE owner's build.
// Verification is done off-device with tools/sign/verify.py; the device only carries the mark
// and never changes its behaviour because of it (a dashboard must stay predictable).
#include <stdint.h>

namespace provenance {
// Keeps the mark referenced (so the linker can't drop it) and returns a checksum over it.
uint32_t mark();
// One short line at boot, proving the bytes are present in this build.
void logBoot();
}
